184	async function handleApiRequest(
185	  c: Context<{ Bindings: Env }>,
186	  route: RouteDefinition,
187	  db: Db,
188	  storage: StorageService,
189	): Promise<Response> {
190	  const env = c.env;
191	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted"
192	    ? "local_trusted" as const
193	    : "authenticated" as const;
194	
195	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
196	
197	  const ctx: import("../../../server/src/http/types.js").RequestCtx = {
198	    method: c.req.method,
199	    url: new URL(c.req.url),
200	    headers: new Headers(c.req.raw.headers),
201	    json<T>(): Promise<T> { return c.req.json<T>(); },
202	    text(): Promise<string> { return c.req.text(); },
203	    param(name: string): string | undefined { return c.req.param(name); },
204	    query(name: string): string | undefined { return c.req.query(name); },
205	    actor,
206	    db,
207	    storage,
208	  };
209	
210	  try {
211	    return await route.handler(ctx);
212	  } catch (err) {
213	    if (err instanceof HttpError) {
214	      return Response.json(
215	        { error: err.message, ...(err.details !== undefined ? { details: err.details } : {}) },
216	        { status: err.status },
217	      );
218	    }
219	    console.error(
220	      `[CF Worker] Unhandled error in ${route.method} ${route.path}: ${
221	        err instanceof Error ? err.stack ?? err.message : String(err)
222	      }`,
223	    );
224	    return Response.json({ error: "Internal Server Error" }, { status: 500 });
225	  }
226	}
